# ── Numpy conv2d (Conv2d + ReLU, no padding) ─────────────────────────────────

def _conv2d(x, W, b, stride):
    """
    x: (C_in, H, W)  W: (C_out, C_in, kH, kW)  b: (C_out,)
    Returns (C_out, H_out, W_out) after ReLU.
    Uses stride_tricks im2col — no Python loops over spatial dims.
    """
    x = np.ascontiguousarray(x, dtype=np.float32)
    C_in, H, Wi = x.shape
    C_out, _, kH, kW = W.shape
    Ho = (H  - kH) // stride + 1
    Wo = (Wi - kW) // stride + 1
    shape   = (Ho, Wo, C_in, kH, kW)
    strides = (x.strides[1] * stride, x.strides[2] * stride,
               x.strides[0], x.strides[1], x.strides[2])
    windows = np.lib.stride_tricks.as_strided(x, shape=shape, strides=strides)
    # (Ho*Wo, C_in*kH*kW) @ (C_out, C_in*kH*kW).T + b → (Ho*Wo, C_out)
    out = windows.reshape(Ho * Wo, -1) @ W.reshape(C_out, -1).T + b
    return np.maximum(0.0, out.reshape(Ho, Wo, C_out).transpose(2, 0, 1))


# ── Numpy forward pass (actor head only) ─────────────────────────────────────

def _forward(obs):
    scalar     = obs[:6          ].astype(np.float32)
    wind_flat  = obs[6:6+32768   ].astype(np.float32)
    world_flat = obs[6+32768:6+32768+16384].astype(np.float32)

    wind  = wind_flat.reshape(2, 128, 128)
    world = world_flat.reshape(1, 128, 128)

    # ── Scalar branch ─────────────────────────────────────────────────────────
    s = np.maximum(0.0, scalar @ _scalar_branch_0_W.T + _scalar_branch_0_b)
    s = np.maximum(0.0, s      @ _scalar_branch_2_W.T + _scalar_branch_2_b)

    # ── Wind branch (CNN) ─────────────────────────────────────────────────────
    w = _conv2d(wind, _wind_branch_0_W, _wind_branch_0_b, stride=4)
    w = _conv2d(w,    _wind_branch_2_W, _wind_branch_2_b, stride=2)
    w = _conv2d(w,    _wind_branch_4_W, _wind_branch_4_b, stride=2)
    w = w.reshape(-1)
    w = np.maximum(0.0, w @ _wind_branch_7_W.T + _wind_branch_7_b)

    # ── World branch (CNN) ────────────────────────────────────────────────────
    m = _conv2d(world, _world_branch_0_W, _world_branch_0_b, stride=4)
    m = _conv2d(m,     _world_branch_2_W, _world_branch_2_b, stride=2)
    m = _conv2d(m,     _world_branch_4_W, _world_branch_4_b, stride=2)
    m = m.reshape(-1)
    m = np.maximum(0.0, m @ _world_branch_7_W.T + _world_branch_7_b)

    # ── Shared trunk ──────────────────────────────────────────────────────────
    h = np.concatenate([s, w, m])
    h = np.maximum(0.0, h @ _trunk_0_W.T + _trunk_0_b)
    h = np.maximum(0.0, h @ _trunk_2_W.T + _trunk_2_b)

    # ── Actor head (logits over 9 actions) ────────────────────────────────────
    return h @ _actor_head_W.T + _actor_head_b


# ── Agent ─────────────────────────────────────────────────────────────────────

class MyAgent(BaseAgent):
    """PPO sailing agent — pure numpy, no torch. Greedy w.r.t. policy logits."""

    def act(self, observation: np.ndarray) -> int:
        return int(np.argmax(_forward(observation)))

    def reset(self) -> None:
        pass

    def seed(self, seed=None) -> None:
        if seed is not None:
            np.random.seed(seed)
